head.script:
scwin.gVar = {
    "cPlaceholder" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > placeholder]<br/>Secret 컴포넌트의 입력값이 없을때 표시될 PlaceHolder 텍스트를 설정합니다.",
    "validation" : [
        "입력창에 PlaceHolder 로 표시될 텍스트를 설정합니다.",
        "입력창이 포커스되면 웹브라우저에 따라 PlaceHolder 텍스트가 사라지거나 유지될 수 있습니다.",
        "PlaceHolder 텍스트는 입력창에 값(바인딩 포함)이 있거나 값을 입력하는 순간 사라집니다.",
        "PlaceHolder 텍스트는 선택 및 복사할 수 없습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정
    con_placeholder.setSelectedIndex(1);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof input_seed !== 'undefined') {
        input_seed.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof input_paste !== 'undefined') {
        input_paste.remove();
    }

    await $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 con_placeholder 에서 선택한 값이 placeholder 속성으로 적용됩니다\nTarget 재생성 시 target1 의 값은 빈값으로 초기화되며, 위 입력창(clipboard_seed)은 클립보드 초기화용, 아래 빈 입력창은 붙여넣기 확인용입니다\n[절차] 위 조건 선택 -> Target 재생성 -> 검증 목적에 따라 아래 중 하나를 수행\n - 텍스트 설정 : 표시 상태 확인 클릭\n - 포커스 : target1 을 클릭하거나 Tab 으로 포커스를 준 상태에서 화면 관찰\n - 값이 있을때 소멸 : 값 설정 클릭 또는 target1 에 직접 타이핑 -> 표시 상태 확인 -> 값 지움 클릭 -> 표시 상태 확인\n - 선택 및 복사 : 위 입력창의 clipboard_seed 를 선택 후 Ctrl+C 하여 클립보드 기준값을 만든 뒤 -> target1 의 PlaceHolder 텍스트 위를 드래그 선택하거나 Ctrl+A 로 전체 선택 후 Ctrl+C -> 선택 상태 확인 클릭 -> 아래 빈 입력창에 Ctrl+V -> 붙여넣기 값 확인 클릭 (클립보드가 clipboard_seed 그대로면 복사되지 않은 것)\n[확인] password 라 화면으로 값을 읽을 수 없으므로 결과창의 렌더 placeholder 속성값 및 입력창 값과 길이, 그리고 화면에 실제로 보이는 PlaceHolder 텍스트로 판정합니다"', '', 'label1');

    // 클립보드 초기화용 입력창 (복사 전후 클립보드 내용을 구분하기 위한 기준값)
    await $c.gcm.createEmptyInput('initValue="clipboard_seed" style="width:200px; height:30px;"', '', 'input_seed');

    // 조건 설정
    scwin.gVar["cPlaceholder"] = con_placeholder.getValue();

    let properties = {
        placeholder : scwin.gVar["cPlaceholder"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onfocus"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);

    // 헬퍼가 넣은 초기값을 지워 값이 없는 상태에서 PlaceHolder 를 확인한다
    target1.setValue("");

    // 붙여넣기 확인용 입력창
    await $c.gcm.createEmptyInput('style="width:200px; height:30px;"', '', 'input_paste');
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 렌더된 placeholder 속성 상태 (속성 미생성과 빈 문자열은 다른 상태이므로 구분해서 표기)
scwin.fn_ph = function () {
    let objInput = target1.render;

    if (!objInput.hasAttribute("placeholder"))
        return "속성 없음";

    let strAttr = objInput.getAttribute("placeholder");

    return (strAttr === "") ? "빈 문자열" : strAttr;
}



// 렌더 placeholder 속성값과 입력창 값 확인 - validation 1, 3 판정 출력
scwin.btn_getState_onclick = function (e) {
    let strValue = target1.getValue() || "";

    wf_body_bottom.getObj("scwin").setReturnValue("placeholder " + scwin.fn_disp(scwin.gVar["cPlaceholder"]) + " -> 렌더 placeholder 속성 : " + scwin.fn_ph() + " / 입력창 값 : " + strValue + " (" + strValue.length + "자)");
}



// 값 주입 (validation 3 발동 수단)
scwin.btn_setValue_onclick = function (e) {
    target1.setValue("inputValue");
}



// 값 제거 (validation 3 발동 수단)
scwin.btn_clearValue_onclick = function (e) {
    target1.setValue("");
}



// 드래그 선택 결과 확인 - validation 4 판정 출력
scwin.btn_getSelection_onclick = function (e) {
    let objInput = target1.render;

    wf_body_bottom.getObj("scwin").setReturnValue("드래그 후 -> 입력창 선택 범위 : " + objInput.selectionStart + " ~ " + objInput.selectionEnd + " / 문서 선택 텍스트 : " + window.getSelection().toString());
}



// 붙여넣기 결과 확인 - validation 4 판정 출력
scwin.btn_getPaste_onclick = function (e) {
    let strPaste = input_paste.getValue() || "";

    wf_body_bottom.getObj("scwin").setReturnValue("붙여넣기 값 : " + strPaste + " (" + strPaste.length + "자)");
}



// 포커스 시점의 표시 상태 확인 - validation 2 판정 출력
scwin.target1_onfocus = function (e) {
    let strValue = target1.getValue() || "";

    wf_body_bottom.getObj("scwin").setReturnValue("포커스 시점 -> 렌더 placeholder 속성 : " + scwin.fn_ph() + " / 입력창 값 : " + strValue + " (" + strValue.length + "자)");
}
